/* prog32_prime_factorization.c
 *
 * Re‑implementation of the original binary's observable behaviour.
 *
 * Behaviour:
 *   - No argument          -> prints "NO_INPUT\n"
 *   - Argument not a number-> prints "BAD_INPUT\n"
 *   - Number > 1e9         -> prints "OUT_OF_RANGE\n"
 *   - Number < 2           -> prints "NONE\n"
 *   - Otherwise            -> prints prime factorisation as
 *                              p1^e1 p2^e2 ... pn^en\n
 * The exponent is always printed, even when it is 1.
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* 1. No argument */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Parse the argument */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* parsing failed or extra characters after the number */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. Range check */
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 4. Numbers smaller than 2 have no prime factors */
    if (n < 2) {
        puts("NONE");
        return 0;
    }

    /* 5. Prime factorisation */
    long remaining = n;
    int first = 1;               /* true for the first factor printed */

    for (long d = 2; d * d <= remaining; ++d) {
        int exp = 0;
        while (remaining % d == 0) {
            ++exp;
            remaining /= d;
        }
        if (exp > 0) {
            if (!first) putchar(' ');
            printf("%ld^%d", d, exp);
            first = 0;
        }
    }

    /* If something is left, it is a prime > sqrt(original n) */
    if (remaining > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", remaining);
    }

    putchar('\n');
    return 0;
}
